; Project Epoch SHA-256 binding profile $01, round8/table experiment.
;
; This is a separate source-only candidate.  It preserves the proven profile,
; caller ABI, scratch layout, invalid-argument behavior, and digest encoding.
; It replaces runtime round indexing and state shuffles with eight-round
; compile-time groups, and evaluates all four SHA-256 sigma functions through
; original generated byte-contribution tables.
;
; This file is an includable Asar source unit.  It contains no mapping
; directive, org, hook, ROM allocation, selected WRAM allocation, or game
; bytes.  The includer supplies:
;
;   !PE_SHA256_SCRATCH = $7Exxxx or $7Fxxxx
;
; The same assembly unit must also place the generated, unmodified include
; ``schala_sidecar_sha256_sigma_tables.asm`` in one independently bounded
; bank.  This core references its EpochSha256SigmaTables_* labels by long
; address but does not place the tables itself.
;
; Entry ABI: EpochSha256Round8_Profile1Digest (JSL / RTL)
; ------------------------------------------------------
; Preconditions:
;   - native mode;
;   - 16-bit accumulator and 16-bit index registers (M=0, X=0);
;   - A = physical save slot number $0001, $0002, or $0003;
;   - X = matching SRAM slot low word $6000, $6A00, or $7400;
;   - bank $30 contains the finalized vanilla save slot.
;
; Results:
;   - caller A/X/Y/P/DBR/D are restored exactly;
;   - scratch +$00A0..+$00BF contains standard big-endian digest bytes;
;   - scratch +$00C0 is $0000 on success or $FFFF for an invalid pair;
;   - invalid arguments do not modify the output span.
;
; Bounds:
;   - reads exactly $0A00 selected bank-$30 bytes;
;   - writes only the caller-provided $00C2-byte scratch span;
;   - maximum stack growth after entry is 14 bytes: the 10-byte save frame
;     plus two nested 2-byte JSR return addresses;
;   - including the caller's 3-byte JSL return, total growth is 17 bytes;
;   - generated code is asserted at or below $6000 bytes in one bank;
;   - generated sigma tables are exactly $4000 bytes in one separate bank;
;   - no sidecar, SRAM, ROM, hook, or checksum bytes are written;
;   - not reentrant and not approved across NMI/IRQ.
;
; Profile $01 message:
;   exact $0A00 slot ||
;   "PE07BIND", $02, $01, physical_slot, $00, $00, $0A, $00, $00
;
; The fixed $0A10-byte message pads to 41 compression blocks.

!PE_SHA256_SCRATCH_LO   = (!PE_SHA256_SCRATCH&$00FFFF)
!PE_SHA256_SCRATCH_BANK = ((!PE_SHA256_SCRATCH>>16)&$FF)
!PE_SHA256_SCRATCH_SIZE = $00C2

assert !PE_SHA256_SCRATCH_BANK == $7E || !PE_SHA256_SCRATCH_BANK == $7F, "round8 SHA scratch must be WRAM"
assert !PE_SHA256_SCRATCH_LO+!PE_SHA256_SCRATCH_SIZE <= $10000, "round8 SHA scratch crosses a bank"

!PE_SHA_STATE       = $0000
!PE_SHA_WORK        = $0020
!PE_SHA_W           = $0040
!PE_SHA_INPUT       = $0080
!PE_SHA_ROT         = $0084
!PE_SHA_SIGMA       = $0088
!PE_SHA_T1          = $008C
!PE_SHA_T2          = $0090
!PE_SHA_TEMP        = $0094
!PE_SHA_CURSOR      = $0098
!PE_SHA_SLOT        = $009A
!PE_SHA_BLOCK       = $009C
!PE_SHA_ROUND       = $009E
!PE_SHA_OUTPUT      = $00A0
!PE_SHA_STATUS      = $00C0

!PE_SHA_A = $00
!PE_SHA_B = $04
!PE_SHA_C = $08
!PE_SHA_D = $0C
!PE_SHA_E = $10
!PE_SHA_F = $14
!PE_SHA_G = $18
!PE_SHA_H = $1C


; Evaluate one sigma transform.  Y names the numeric-high half of the
; 32-bit input in scratch.  The four generated tables are indexed by
; conceptual input bytes b0..b3, not by little-endian memory order.
macro EpochSha256Round8_TableSigma(byte0, byte1, byte2, byte3)
    ; Byte0 = bits 31..24 = scratch[Y]+1.
    LDA.w !PE_SHA256_SCRATCH_LO+$0000,Y
    XBA
    AND.w #$00FF
    ASL A
    ASL A
    TAX
    LDA.l <byte0>,X
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    LDA.l <byte0>+$0002,X
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2

    ; Byte1 = bits 23..16 = scratch[Y].
    LDA.w !PE_SHA256_SCRATCH_LO+$0000,Y
    AND.w #$00FF
    ASL A
    ASL A
    TAX
    LDA.l <byte1>,X
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    LDA.l <byte1>+$0002,X
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2

    ; Byte2 = bits 15..8 = scratch[Y]+3.
    LDA.w !PE_SHA256_SCRATCH_LO+$0002,Y
    XBA
    AND.w #$00FF
    ASL A
    ASL A
    TAX
    LDA.l <byte2>,X
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    LDA.l <byte2>+$0002,X
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2

    ; Byte3 = bits 7..0 = scratch[Y]+2.
    LDA.w !PE_SHA256_SCRATCH_LO+$0002,Y
    AND.w #$00FF
    ASL A
    ASL A
    TAX
    LDA.l <byte3>,X
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    LDA.l <byte3>+$0002,X
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
endmacro


; Expand circular W[round&15] for rounds 16..63.  All indices are compile-time
; constants: W[t-16], W[t-15], W[t-7], and W[t-2].
macro EpochSha256Round8_Expand(round)
    LDY.w #!PE_SHA_W+(((<round>+$0001)&$000F)*4)
    JSR.w EpochSha256Round8_SmallSigma0

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$0002+((<round>&$000F)*4)
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+((<round>&$000F)*4)
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$0002+(((<round>+$0009)&$000F)*4)
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+(((<round>+$0009)&$000F)*4)
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP

    LDY.w #!PE_SHA_W+(((<round>+$000E)&$000F)*4)
    JSR.w EpochSha256Round8_SmallSigma1

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP

    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+((<round>&$000F)*4)
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$0002+((<round>&$000F)*4)
endmacro


; One SHA-256 round.  The a..h parameters are physical offsets in WORK.
; Symbolic rotation means only new e (old d) and new a (old h) are written.
macro EpochSha256Round8_Round(round, a, b, c, d, e, f, g, h, khi, klo)
if <round> >= $0010
    %EpochSha256Round8_Expand(<round>)
endif

    ; T1 = h + Sigma1(e) + Ch(e,f,g) + K[round] + W[round].
    LDY.w #!PE_SHA_WORK+<e>
    JSR.w EpochSha256Round8_BigSigma1

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<h>+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<h>
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1

    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<f>
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<g>
    AND.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<e>
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<g>
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<f>+2
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<g>+2
    AND.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<e>+2
    EOR.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<g>+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    ADC.w #<klo>
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1
    ADC.w #<khi>
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$0002+((<round>&$000F)*4)
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+((<round>&$000F)*4)
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1

    ; T2 = Sigma0(a) + Maj(a,b,c).
    LDY.w #!PE_SHA_WORK+<a>
    JSR.w EpochSha256Round8_BigSigma0

    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<a>
    AND.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<b>
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<a>
    ORA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<b>
    AND.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<c>
    ORA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP

    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<a>+2
    AND.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<b>+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<a>+2
    ORA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<b>+2
    AND.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<c>+2
    ORA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T2+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SIGMA
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_TEMP
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T2

    ; New e occupies old d; new a occupies old h.  The next macro invocation
    ; rotates symbolic parameters instead of copying the other six words.
    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<d>+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<d>+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<d>
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<d>

    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1+2
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T2+2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<h>+2
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T1
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_T2
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+<h>
endmacro


; Eight rounds restore the physical a..h layout.  K halves are supplied as
; compile-time macro arguments, eliminating the runtime K table and index.
macro EpochSha256Round8_Group(base, k0h, k0l, k1h, k1l, k2h, k2l, k3h, k3l, k4h, k4l, k5h, k5l, k6h, k6l, k7h, k7l)
    %EpochSha256Round8_Round(<base>+$00, !PE_SHA_A, !PE_SHA_B, !PE_SHA_C, !PE_SHA_D, !PE_SHA_E, !PE_SHA_F, !PE_SHA_G, !PE_SHA_H, <k0h>, <k0l>)
    %EpochSha256Round8_Round(<base>+$01, !PE_SHA_H, !PE_SHA_A, !PE_SHA_B, !PE_SHA_C, !PE_SHA_D, !PE_SHA_E, !PE_SHA_F, !PE_SHA_G, <k1h>, <k1l>)
    %EpochSha256Round8_Round(<base>+$02, !PE_SHA_G, !PE_SHA_H, !PE_SHA_A, !PE_SHA_B, !PE_SHA_C, !PE_SHA_D, !PE_SHA_E, !PE_SHA_F, <k2h>, <k2l>)
    %EpochSha256Round8_Round(<base>+$03, !PE_SHA_F, !PE_SHA_G, !PE_SHA_H, !PE_SHA_A, !PE_SHA_B, !PE_SHA_C, !PE_SHA_D, !PE_SHA_E, <k3h>, <k3l>)
    %EpochSha256Round8_Round(<base>+$04, !PE_SHA_E, !PE_SHA_F, !PE_SHA_G, !PE_SHA_H, !PE_SHA_A, !PE_SHA_B, !PE_SHA_C, !PE_SHA_D, <k4h>, <k4l>)
    %EpochSha256Round8_Round(<base>+$05, !PE_SHA_D, !PE_SHA_E, !PE_SHA_F, !PE_SHA_G, !PE_SHA_H, !PE_SHA_A, !PE_SHA_B, !PE_SHA_C, <k5h>, <k5l>)
    %EpochSha256Round8_Round(<base>+$06, !PE_SHA_C, !PE_SHA_D, !PE_SHA_E, !PE_SHA_F, !PE_SHA_G, !PE_SHA_H, !PE_SHA_A, !PE_SHA_B, <k6h>, <k6l>)
    %EpochSha256Round8_Round(<base>+$07, !PE_SHA_B, !PE_SHA_C, !PE_SHA_D, !PE_SHA_E, !PE_SHA_F, !PE_SHA_G, !PE_SHA_H, !PE_SHA_A, <k7h>, <k7l>)
endmacro


EpochSha256Round8_SourceStart:
EpochSha256Round8_Profile1Digest:
    PHP
    REP #$30
    CLD
    PHA
    PHX
    PHY
    PHD
    PHB

    STA.l !PE_SHA256_SCRATCH+!PE_SHA_SLOT
    TXA
    STA.l !PE_SHA256_SCRATCH+!PE_SHA_CURSOR

    SEP #$20
    LDA.b #!PE_SHA256_SCRATCH_BANK
    PHA
    PLB
    REP #$30

    LDA.w #$FFFF
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATUS

    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SLOT
    CMP.w #$0001
    BEQ .ValidateSlot1
    CMP.w #$0002
    BEQ .ValidateSlot2
    CMP.w #$0003
    BEQ .ValidateSlot3
    BRL .Return

.ValidateSlot1:
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_CURSOR
    CMP.w #$6000
    BEQ .ArgumentsValid
    BRL .Return

.ValidateSlot2:
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_CURSOR
    CMP.w #$6A00
    BEQ .ArgumentsValid
    BRL .Return

.ValidateSlot3:
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_CURSOR
    CMP.w #$7400
    BEQ .ArgumentsValid
    BRL .Return

.ArgumentsValid:
    JSR.w EpochSha256Round8_InitializeState
    STZ.w !PE_SHA256_SCRATCH_LO+!PE_SHA_BLOCK

.SlotBlockLoop:
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_BLOCK
    CMP.w #$0028
    BEQ .FinalBlock
    JSR.w EpochSha256Round8_LoadSlotBlock
    JSR.w EpochSha256Round8_CompressBlock
    INC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_BLOCK
    BRL .SlotBlockLoop

.FinalBlock:
    JSR.w EpochSha256Round8_LoadProfile1FinalBlock
    JSR.w EpochSha256Round8_CompressBlock
    JSR.w EpochSha256Round8_EmitDigest
    STZ.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATUS

.Return:
    PLB
    PLD
    PLY
    PLX
    PLA
    PLP
    RTL


EpochSha256Round8_InitializeState:
    LDX.w #$0000
.Loop:
    LDA.l EpochSha256Round8_InitialState,X
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE,X
    INX
    INX
    CPX.w #$0020
    BNE .Loop
    RTS


EpochSha256Round8_LoadSlotBlock:
    LDX.w !PE_SHA256_SCRATCH_LO+!PE_SHA_CURSOR
    LDY.w #$0000
.WordLoop:
    LDA.l $300000,X
    XBA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W,Y
    INX
    INX
    LDA.l $300000,X
    XBA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+2,Y
    INX
    INX
    TYA
    CLC
    ADC.w #$0004
    TAY
    CPY.w #$0040
    BNE .WordLoop
    STX.w !PE_SHA256_SCRATCH_LO+!PE_SHA_CURSOR
    RTS


EpochSha256Round8_LoadProfile1FinalBlock:
    LDX.w #$0000
.ZeroLoop:
    STZ.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W,X
    INX
    INX
    CPX.w #$0040
    BNE .ZeroLoop

    LDA.w #$5045
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$00
    LDA.w #$3037
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$02
    LDA.w #$4249
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$04
    LDA.w #$4E44
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$06
    LDA.w #$0201
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$08
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_SLOT
    XBA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$0A
    LDA.w #$000A
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$0C
    LDA.w #$8000
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$10
    LDA.w #$5080
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_W+$3E
    RTS


EpochSha256Round8_CompressBlock:
    LDX.w #$0000
.CopyState:
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE,X
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK,X
    INX
    INX
    CPX.w #$0020
    BNE .CopyState

EpochSha256Round8_Group00_Start:
    %EpochSha256Round8_Group($00, $428A, $2F98, $7137, $4491, $B5C0, $FBCF, $E9B5, $DBA5, $3956, $C25B, $59F1, $11F1, $923F, $82A4, $AB1C, $5ED5)
EpochSha256Round8_Group00_End:

EpochSha256Round8_Group01_Start:
    %EpochSha256Round8_Group($08, $D807, $AA98, $1283, $5B01, $2431, $85BE, $550C, $7DC3, $72BE, $5D74, $80DE, $B1FE, $9BDC, $06A7, $C19B, $F174)
EpochSha256Round8_Group01_End:

EpochSha256Round8_Group02_Start:
    %EpochSha256Round8_Group($10, $E49B, $69C1, $EFBE, $4786, $0FC1, $9DC6, $240C, $A1CC, $2DE9, $2C6F, $4A74, $84AA, $5CB0, $A9DC, $76F9, $88DA)
EpochSha256Round8_Group02_End:

EpochSha256Round8_Group03_Start:
    %EpochSha256Round8_Group($18, $983E, $5152, $A831, $C66D, $B003, $27C8, $BF59, $7FC7, $C6E0, $0BF3, $D5A7, $9147, $06CA, $6351, $1429, $2967)
EpochSha256Round8_Group03_End:

EpochSha256Round8_Group04_Start:
    %EpochSha256Round8_Group($20, $27B7, $0A85, $2E1B, $2138, $4D2C, $6DFC, $5338, $0D13, $650A, $7354, $766A, $0ABB, $81C2, $C92E, $9272, $2C85)
EpochSha256Round8_Group04_End:

EpochSha256Round8_Group05_Start:
    %EpochSha256Round8_Group($28, $A2BF, $E8A1, $A81A, $664B, $C24B, $8B70, $C76C, $51A3, $D192, $E819, $D699, $0624, $F40E, $3585, $106A, $A070)
EpochSha256Round8_Group05_End:

EpochSha256Round8_Group06_Start:
    %EpochSha256Round8_Group($30, $19A4, $C116, $1E37, $6C08, $2748, $774C, $34B0, $BCB5, $391C, $0CB3, $4ED8, $AA4A, $5B9C, $CA4F, $682E, $6FF3)
EpochSha256Round8_Group06_End:

EpochSha256Round8_Group07_Start:
    %EpochSha256Round8_Group($38, $748F, $82EE, $78A5, $636F, $84C8, $7814, $8CC7, $0208, $90BE, $FFFA, $A450, $6CEB, $BEF9, $A3F7, $C671, $78F2)
EpochSha256Round8_Group07_End:

    ; Every group ends with the physical a..h mapping canonical again.
    LDX.w #$0000
.StateAddLoop:
    CLC
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE+2,X
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK+2,X
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE+2,X
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE,X
    ADC.w !PE_SHA256_SCRATCH_LO+!PE_SHA_WORK,X
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE,X
    TXA
    CLC
    ADC.w #$0004
    TAX
    CPX.w #$0020
    BNE .StateAddLoop
    RTS


EpochSha256Round8_BigSigma0:
    %EpochSha256Round8_TableSigma(EpochSha256SigmaTables_BigSigma0_Byte0, EpochSha256SigmaTables_BigSigma0_Byte1, EpochSha256SigmaTables_BigSigma0_Byte2, EpochSha256SigmaTables_BigSigma0_Byte3)
    RTS


EpochSha256Round8_BigSigma1:
    %EpochSha256Round8_TableSigma(EpochSha256SigmaTables_BigSigma1_Byte0, EpochSha256SigmaTables_BigSigma1_Byte1, EpochSha256SigmaTables_BigSigma1_Byte2, EpochSha256SigmaTables_BigSigma1_Byte3)
    RTS


EpochSha256Round8_SmallSigma0:
    %EpochSha256Round8_TableSigma(EpochSha256SigmaTables_SmallSigma0_Byte0, EpochSha256SigmaTables_SmallSigma0_Byte1, EpochSha256SigmaTables_SmallSigma0_Byte2, EpochSha256SigmaTables_SmallSigma0_Byte3)
    RTS


EpochSha256Round8_SmallSigma1:
    %EpochSha256Round8_TableSigma(EpochSha256SigmaTables_SmallSigma1_Byte0, EpochSha256SigmaTables_SmallSigma1_Byte1, EpochSha256SigmaTables_SmallSigma1_Byte2, EpochSha256SigmaTables_SmallSigma1_Byte3)
    RTS


EpochSha256Round8_EmitDigest:
    LDX.w #$0000
.Loop:
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE,X
    XBA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_OUTPUT,X
    LDA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_STATE+2,X
    XBA
    STA.w !PE_SHA256_SCRATCH_LO+!PE_SHA_OUTPUT+2,X
    TXA
    CLC
    ADC.w #$0004
    TAX
    CPX.w #$0020
    BNE .Loop
    RTS


EpochSha256Round8_InitialState:
    dw $6A09,$E667
    dw $BB67,$AE85
    dw $3C6E,$F372
    dw $A54F,$F53A
    dw $510E,$527F
    dw $9B05,$688C
    dw $1F83,$D9AB
    dw $5BE0,$CD19
EpochSha256Round8_InitialState_End:

assert EpochSha256Round8_InitialState_End-EpochSha256Round8_InitialState == $0020, "round8 SHA initial table size"
assert bank(EpochSha256Round8_InitialState) == bank(EpochSha256Round8_InitialState_End-1), "round8 SHA initial table crosses bank"


EpochSha256Round8_SourceEnd:

assert EpochSha256Round8_SourceEnd-EpochSha256Round8_SourceStart <= $6000, "round8 SHA generated code exceeds $6000"
assert bank(EpochSha256Round8_SourceStart) == bank(EpochSha256Round8_SourceEnd-1), "round8 SHA source crosses a bank"
